import numpy as np; exec("class Solution:\n    def train(self, X, y, epochs, lr):\n        X = np.array(X, dtype=np.float64)\n        y = np.array(y, dtype=np.float64)\n        n = X.shape[0]\n        w = np.zeros(X.shape[1], dtype=np.float64)\n        b = 0.0\n        for _ in range(epochs):\n            y_hat = X @ w + b\n            error = y_hat - y\n            dw = (2/n) * (X.T @ error)\n            db = (2/n) * np.sum(error)\n            w = w - lr * dw\n            b = b - lr * db\n        return (np.round(w, 5).tolist(), round(float(b), 5))")